Fusing both ends of the MoE bookkeeping. Routing does the 60-way dot, sigmoid, bias top-4 and normalize in one threadgroup per row, caching `x` in threadgroup memory. Combine does the 4-way weighted sum plus shared add in one memory-bound kernel, mimicking the reference's two roundings.

```metal
uint row = threadgroup_position_in_grid.x;
uint tid = thread_position_in_threadgroup.x;
threadgroup float xcache[768];
threadgroup float sc[60];
for (uint k = tid; k < 768; k += 64) {
    xcache[k] = static_cast<float>(x[row * 768 + k]);
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid < 60) {
    const device float* wptr = w_router + tid * 768;
    float acc = 0.0f;
    for (uint k = 0; k < 768; ++k) {
        acc += xcache[k] * wptr[k];
    }
    float sig = 1.0f / (1.0f + metal::exp(-acc));
    sc[tid] = sig;
}
threadgroup_barrier(mem_flags::mem_threadgroup);
if (tid == 0) {
    uint top_idx[4] = {0, 0, 0, 0};
    float top_b[4] = {-1e30f, -1e30f, -1e30f, -1e30f};
    for (uint e = 0; e < 60; ++e) {
        float b = sc[e] + bias[e];
        if (b > top_b[0]) {
            top_b[3] = top_b[2]; top_idx[3] = top_idx[2];
            top_b[2] = top_b[1]; top_idx[2] = top_idx[1];
            top_b[1] = top_b[0]; top_idx[1] = top_idx[0];
            top_b[0] = b; top_idx[0] = e;
        } else if (b > top_b[1]) {
            top_b[3] = top_b[2]; top_idx[3] = top_idx[2];
            top_b[2] = top_b[1]; top_idx[2] = top_idx[1];
            top_b[1] = b; top_idx[1] = e;
        } else if (b > top_b[2]) {
            top_b[3] = top_b[2]; top_idx[3] = top_idx[2];
            top_b[2] = b; top_idx[2] = e;
        } else if (b > top_b[3]) {
            top_b[3] = b; top_idx[3] = e;
        }
    }
    float s0 = sc[top_idx[0]];
    float s1 = sc[top_idx[1]];
    float s2 = sc[top_idx[2]];
    float s3 = sc[top_idx[3]];
    float sum = s0 + s1 + s2 + s3;
    float inv = 2.5f / (sum + 1e-20f);
    inds[row * 4 + 0] = top_idx[0];
    inds[row * 4 + 1] = top_idx[1];
    inds[row * 4 + 2] = top_idx[2];
    inds[row * 4 + 3] = top_idx[3];
    weights[row * 4 + 0] = s0 * inv;
    weights[row * 4 + 1] = s1 * inv;
    weights[row * 4 + 2] = s2 * inv;
    weights[row * 4 + 3] = s3 * inv;
}
```

```metal
uint idx = thread_position_in_grid.x;
uint r = idx / 768;
uint c = idx % 768;
float w0 = weights[r * 4 + 0];
float w1 = weights[r * 4 + 1];
float w2 = weights[r * 4 + 2];
float w3 = weights[r * 4 + 3];
const device bfloat* yrow = y + r * 3072;
float y0 = static_cast<float>(yrow[0 * 768 + c]);
float y1 = static_cast<float>(yrow[1 * 768 + c]);
float y2 = static_cast<float>(yrow[2 * 768 + c]);
float y3 = static_cast<float>(yrow[3 * 768 + c]);
float sum = w0 * y0 + w1 * y1 + w2 * y2 + w3 * y3;
bfloat sum_bf = static_cast<bfloat>(sum);
float sh = static_cast<float>(shared[r * 768 + c]);
float res = static_cast<float>(sum_bf) + sh;
out[idx] = static_cast<bfloat>(res);
```

